    for (int x = 0; x < p->w; x++) n += halo_get_bit(p, x, y);
  return n;
}

static void set_bit(HaloPlane *p, int x, int y) {
  p->bits[(size_t)y * (size_t)p->stride + (size_t)(x >> 3)] |=
      (uint8_t)(0x80 >> (x & 7));
}

static void scatter(HaloPlane *p, unsigned seed) {
  srandom(seed);
  for (int y = 0; y < p->h; y++)
    for (int x = 0; x < p->w; x++)
      if (random() & 1) set_bit(p, x, y);
}

