  TEST_ASSERT_EQUAL_INT(1, halo_get_bit(plane(p), 2, 1));
  moire2_fill_rectangle(dpy, p, nothing, 0, 0, 20, 6);
  TEST_ASSERT_EQUAL_INT(20 * 6 - 8 * 2, count_set(plane(p)));
