      if (b == (x1 >> 3)) mask &= (uint8_t)(0xFF << (7 - (x1 & 7)));
      const uint8_t bits = (uint8_t)(moire2_bits_at(srow, s->stride,
                                                    sx + b * 8 - dx) & mask);
      if (gc->function == GXor)
        drow[b] |= bits;
      else if (gc->function == GXxor)
        drow[b] ^= bits;
      else
