  glClear(GL_COLOR_BUFFER_BIT);
  TEST_ASSERT_EQUAL_HEX16(rgb565(255, 0, 0), wide.px[0]);
  TEST_ASSERT_EQUAL_HEX16(rgb565(255, 0, 0), wide.px[65]);

